def cut(n, name):
    res=[];inroot=False;steps=0;skip=False
    for l in txt:
        f=l.split(None,2)
        if f[:2]==['0','FILE']:
            inroot=(f[2].strip()==root); skip=False
        if inroot:
            if skip: 
                if f[:2]==['0','NOFILE']: res.append(l)
                continue
            res.append(l)
            if f[:2] in (['0','STEP'],['0','ROTSTEP']):
                steps+=1
                if steps>=n: skip=True
        else: res.append(l)
    (out/name).write_text('\r\n'.join(res),encoding='utf-8')
